sku_list = [p['SKU'] for p in products]
revenue = {p['SKU']: float(p['Revenue']) for p in products}
demand = {p['SKU']: int(p['Demand']) for p in products}
init_inventory = {p['SKU']: float(p['Initial Inventory']) for p in products}
for sku in sku_list:
    if sku not in revenue or sku not in demand or sku not in init_inventory:
        raise ValueError(f'Missing data for SKU {sku}')
m = gp.Model('ZZ_Product_Fulfillment')
x_vars = m.addVars(sku_list, vtype=GRB.INTEGER, lb=0, name='')
for sku in sku_list:
    upper = min(init_inventory[sku], demand[sku])
    m.addConstr(x_vars[sku] <= upper, name='ub_' + sku)
m.setObjective(gp.quicksum((revenue[sku] * x_vars[sku] for sku in sku_list)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for sku in sku_list:
        print(f'x[{sku}]: {x_vars[sku].X}')
else:
    print(f'Solver status: {m.Status}')